// PARENT — the INVERSE (non-owning) side. mappedBy points at Trade.account
package com.bank.trading.model;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;

@Entity
@Table(name = "accounts")
public class Account {

    @Id
    @Column(name = "account_id")
    private String accountId;

    @Column(name = "holder_name", nullable = false)
    private String holderName;

    private BigDecimal balance;

    // INVERSE side: mappedBy = name of the owning FIELD on Trade (not a column!)
    // cascade ALL → saving the account also saves its trades
    // orphanRemoval → a trade removed from this list is DELETEd
    @OneToMany(mappedBy = "account", cascade = CascadeType.ALL, orphanRemoval = true)
    private List<Trade> trades = new ArrayList<>();

    protected Account() {}

    public Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId;
        this.holderName = holderName;
        this.balance = balance;
    }

    // SYNC HELPER — updates BOTH sides so the FK is never NULL
    public void addTrade(Trade trade) {
        trades.add(trade);        // inverse side (in-memory navigation)
        trade.setAccount(this);   // owning side (what Hibernate actually persists)
    }

    public void removeTrade(Trade trade) {
        trades.remove(trade);
        trade.setAccount(null);   // orphanRemoval will DELETE it on flush
    }

    public String getAccountId() { return accountId; }
    public String getHolderName() { return holderName; }
    public BigDecimal getBalance() { return balance; }
    public List<Trade> getTrades() { return trades; }
}
