// CHILD — the OWNING side. Its table holds the account_id FK column.
package com.bank.trading.model;

import jakarta.persistence.*;
import java.math.BigDecimal;

@Entity
@Table(name = "trades")
public class Trade {

    @Id
    @Column(name = "trade_id")
    private String tradeId;

    // OWNING side: @JoinColumn names the actual FK column on the trades table
    // override default EAGER → LAZY
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "account_id")
    private Account account;

    private String symbol;
    private BigDecimal amount;
    private String status;

    protected Trade() {}

    public Trade(String tradeId, String symbol, BigDecimal amount) {
        this.tradeId = tradeId;
        this.symbol = symbol;
        this.amount = amount;
        this.status = "SETTLED";
    }

    public String getTradeId() { return tradeId; }
    public String getSymbol() { return symbol; }
    public BigDecimal getAmount() { return amount; }
    public String getStatus() { return status; }
    public Account getAccount() { return account; }
    public void setAccount(Account account) { this.account = account; }
}
