package com.bank.trading.dto;

import com.bank.trading.model.Account;
import java.math.BigDecimal;
import java.util.List;

public record AccountWithTrades(
    String accountId, String holderName, BigDecimal balance, List<TradeLine> trades
) {
    public record TradeLine(String tradeId, String symbol, BigDecimal amount, String status) {}

    public static AccountWithTrades from(Account a) {
        return new AccountWithTrades(a.getAccountId(), a.getHolderName(), a.getBalance(),
            a.getTrades().stream()
                .map(t -> new TradeLine(t.getTradeId(), t.getSymbol(), t.getAmount(), t.getStatus()))
                .toList());
    }
}
