package com.bank.trading.service;

import com.bank.trading.dto.AccountWithTrades;
import com.bank.trading.model.Account;
import com.bank.trading.model.Trade;
import com.bank.trading.repository.AccountRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;

@Service
@RequiredArgsConstructor
@Slf4j
public class TradingService {

    private final AccountRepository accountRepo;

    // Add trades through the sync helper → cascade inserts children in one save
    @Transactional
    public AccountWithTrades placeTrades(String accountId) {
        Account account = accountRepo.findById(accountId).orElseThrow();

        Trade t1 = new Trade("TRD-" + System.nanoTime(), "RELIANCE", new BigDecimal("245050"));
        Trade t2 = new Trade("TRD-" + (System.nanoTime() + 1), "TCS", new BigDecimal("176000"));

        account.addTrade(t1);   // sets t1.account = this → FK will be correct
        account.addTrade(t2);

        accountRepo.save(account);  // cascade ALL → INSERT both trades, account_id set
        log.info("Placed 2 trades on {} — cascade inserted children, FK not NULL", accountId);
        return AccountWithTrades.from(account);
    }

    // Remove a trade → orphanRemoval DELETEs the row
    @Transactional
    public AccountWithTrades cancelTrade(String accountId, String tradeId) {
        Account account = accountRepo.findWithTrades(accountId).orElseThrow();
        account.getTrades().stream()
            .filter(t -> t.getTradeId().equals(tradeId))
            .findFirst()
            .ifPresent(account::removeTrade);  // orphanRemoval → DELETE FROM trades
        accountRepo.save(account);
        log.info("Cancelled trade {} on {} — orphan removed", tradeId, accountId);
        return AccountWithTrades.from(account);
    }

    @Transactional(readOnly = true)
    public AccountWithTrades view(String accountId) {
        return AccountWithTrades.from(accountRepo.findWithTrades(accountId).orElseThrow());
    }
}
