package com.bank.trading.controller;

import com.bank.trading.dto.AccountWithTrades;
import com.bank.trading.service.TradingService;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/v1/trading")
@RequiredArgsConstructor
public class TradingController {

    private final TradingService service;

    @PostMapping("/{accountId}/trades")
    public AccountWithTrades place(@PathVariable String accountId) {
        return service.placeTrades(accountId);
    }

    @DeleteMapping("/{accountId}/trades/{tradeId}")
    public AccountWithTrades cancel(@PathVariable String accountId, @PathVariable String tradeId) {
        return service.cancelTrade(accountId, tradeId);
    }

    @GetMapping("/{accountId}")
    public AccountWithTrades view(@PathVariable String accountId) {
        return service.view(accountId);
    }
}
