// ─── File: src/test/java/com/bank/trading/service/RelationshipSyncTest.java ───
package com.bank.trading.service;

import com.bank.trading.model.Account;
import com.bank.trading.model.Trade;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;

class RelationshipSyncTest {

    @Test
    void addTradeSetsBothSides() {
        Account account = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Trade trade = new Trade("TRD-001", "RELIANCE", new BigDecimal("245050"));

        account.addTrade(trade);

        // inverse side updated
        assertThat(account.getTrades()).containsExactly(trade);
        // OWNING side updated — this is what fills account_id, preventing NULL FK
        assertThat(trade.getAccount()).isSameAs(account);
    }

    @Test
    void removeTradeClearsOwningSide() {
        Account account = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Trade trade = new Trade("TRD-001", "RELIANCE", new BigDecimal("245050"));
        account.addTrade(trade);

        account.removeTrade(trade);

        assertThat(account.getTrades()).isEmpty();
        assertThat(trade.getAccount()).isNull(); // becomes an orphan → DELETE on flush
    }

    @Test
    void mappedByNamesTheOwningField() {
        // @OneToMany(mappedBy="account") → "account" is the FIELD on Trade, not a column.
        // The FK column is named by @JoinColumn(name="account_id") on Trade.
        assertThat("account").isNotEqualTo("account_id");
    }
}
```
